                    let pos0 = offset;
                    meshData[pos0 + 0] = -0.5;
                    meshData[pos0 + 1] = -0.5;
                    meshData[pos0 + 2] = 0;
                    meshData[pos0 + 3] = 0;
                    let pos1 = offset + meshFloatStride;
                    meshData[pos1 + 0] = 0.5;
                    meshData[pos1 + 1] = -0.5;
                    meshData[pos1 + 2] = 1;
                    meshData[pos1 + 3] = 0;
                    let pos2 = offset + 2 * meshFloatStride;
                    meshData[pos2 + 0] = 0.5;
                    meshData[pos2 + 1] = 0.5;
                    meshData[pos2 + 2] = 1;
                    meshData[pos2 + 3] = 1;
                    let pos3 = offset + 3 * meshFloatStride;
                    meshData[pos3 + 0] = -0.5;
                    meshData[pos3 + 1] = 0.5;
                    meshData[pos3 + 2] = 0;
                    meshData[pos3 + 3] = 1;
