            TileMapUtils.transfromPointNByValue(this._matrix, halfw, -halfh, p);
            this._polygons.push(p.x, p.y);
            TileMapUtils.transfromPointNByValue(this._matrix, halfw, halfh, p);
            this._polygons.push(p.x, p.y);
            TileMapUtils.transfromPointNByValue(this._matrix, -halfw, halfh, p);
